/** A `SentenceReviewCard` with an explicit SRS history — for weighting tests. */
function sentenceCardWith(
	sentenceId: string,
	property: string,
	easeFactor: number,
	lapseCount: number,
	repetitions: number,
): SentenceReviewCard {
	return SentenceReviewCard.fromDTO({
